import{_ as a,a0 as l,w as i,s as p,I as o,x as n,a1 as d,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"為LUKS加密的磁盤/分區做增量備份 | LCTT x X-CMD","titleTemplate":false,"description":"為LUKS加密的磁盤/分區做增量備份 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為LUKS加密的磁盤/分區做增量備份 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為LUKS加密的磁盤/分區做增量備份 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150225 How to make remote incremental backup of LUKS-encrypted disk or partition","title":"為LUKS加密的磁盤/分區做增量備份","tag":"201506","desc":""},"relativePath":"201506/20150225 How to make remote incremental backup of LUKS-encrypted disk or partition.md","filePath":"[post].md"}'),u={name:"201506/20150225 How to make remote incremental backup of LUKS-encrypted disk or partition.md"};function m(b,t,y,L,f,S){const e=l("Link");return i(),p("div",null,[t[24]||(t[24]=o("h1",{id:"為luks加密的磁盤-分區做增量備份",tabindex:"-1"},[n("為LUKS加密的磁盤/分區做增量備份 "),o("a",{class:"header-anchor",href:"#為luks加密的磁盤-分區做增量備份","aria-label":"Permalink to “為LUKS加密的磁盤/分區做增量備份”"},"​")],-1)),o("p",null,[t[2]||(t[2]=n("我們中有些人出於安全原因，在家裏或者",-1)),d(e,{href:"http://xmodulo.com/go/digitalocean"},{default:s(()=>[...t[0]||(t[0]=[n("VPS",-1)])]),_:1}),t[3]||(t[3]=n("上通過",-1)),d(e,{href:"http://xmodulo.com/how-to-create-encrypted-disk-partition-on-linux.html"},{default:s(()=>[...t[1]||(t[1]=[n("Linux統一密鑰配置（LUKS）",-1)])]),_:1}),t[4]||(t[4]=n("為硬盤驅動器加密，而這些驅動器的容量很快會增長到數十或數百GB。因此，雖然我們享受着LUKS設備帶來的安全感，但是我們也該開始考慮一個可能的遠程備份方案了。對於安全的非現場備份，我們將需要能在LUKS加密的設備上以塊級別操作的東西。因此，最後我們發現這麼個狀況，我們每次都需要傳輸想要做備份的整個LUKS設備（比如説200GB大）。很明顯，這是不可行的。我們該怎麼來處理這個問題呢？",-1))]),t[25]||(t[25]=o("h3",{id:"一個解決方案-bdsync",tabindex:"-1"},[n("一個解決方案： Bdsync "),o("a",{class:"header-anchor",href:"#一個解決方案-bdsync","aria-label":"Permalink to “一個解決方案： Bdsync”"},"​")],-1)),o("p",null,[t[6]||(t[6]=n("這時，一個卓越的開源工具來拯救我們了，它叫",-1)),d(e,{href:"http://bdsync.rolf-fokkens.nl/"},{default:s(()=>[...t[5]||(t[5]=[n("Bdsync",-1)])]),_:1}),t[7]||(t[7]=n("（多虧了Rolf Fokkens）。顧名思義，Bdsync可以通過網絡同步“塊設備”。對於快速同步，Bdsync會生成並對比本地/遠程塊設備的塊的MD5校驗和，只同步差異部分。rsync在文件系統級別可以做的，Bdsync可以在塊設備級別完成。很自然，對於LUKS加密的設備它也能工作得很好。相當地靈巧！",-1))]),t[26]||(t[26]=r(`<p>使用Bdsync，首次備份將拷貝整個LUKS塊設備到遠程主機，因而會花費大量時間來完成。然而，在初始備份後，如果我們在LUKS設備新建一些文件，再次備份就會很快完成，因為我們只需拷貝修改過的塊。經典的增量備份在起作用了！</p><h3 id="安裝bdsync到linux" tabindex="-1">安裝Bdsync到Linux <a class="header-anchor" href="#安裝bdsync到linux" aria-label="Permalink to “安裝Bdsync到Linux”">​</a></h3><p>Bdsync並不包含在Linux發行版的標準倉庫中，因而你需要從源代碼來構建它。使用以下針對特定版本的指令來安裝Bdsync及其手冊頁到你的系統中。</p><h4 id="debian-ubuntu或linux-mint" tabindex="-1">Debian，Ubuntu或Linux Mint <a class="header-anchor" href="#debian-ubuntu或linux-mint" aria-label="Permalink to “Debian，Ubuntu或Linux Mint”">​</a></h4><pre><code>$ sudo apt-get install git gcc libssl-dev
$ git clone https://github.com/TargetHolding/bdsync.git
$ cd bdsync
$ make
$ sudo cp bdsync /usr/local/sbin
$ sudo mkdir -p /usr/local/man/man1
$ sudo sh -c &#39;gzip -c bdsync.1 &gt; /usr/local/man/man1/bdsync.1.gz&#39;
</code></pre><h4 id="fedora或centos-rhel" tabindex="-1">Fedora或CentOS/RHEL <a class="header-anchor" href="#fedora或centos-rhel" aria-label="Permalink to “Fedora或CentOS/RHEL”">​</a></h4><pre><code>$ sudo yum install git gcc openssl-devel
$ git clone https://github.com/TargetHolding/bdsync.git
$ cd bdsync
$ make
$ sudo cp bdsync /usr/local/sbin
$ sudo mkdir -p /usr/local/man/man1
$ sudo sh -c &#39;gzip -c bdsync.1 &gt; /usr/local/man/man1/bdsync.1.gz&#39;
</code></pre><h3 id="對luks加密的設備實施非現場增量備份" tabindex="-1">對LUKS加密的設備實施非現場增量備份 <a class="header-anchor" href="#對luks加密的設備實施非現場增量備份" aria-label="Permalink to “對LUKS加密的設備實施非現場增量備份”">​</a></h3><p>我假定你已經準備好了一個LUKS加密的塊設備作為備份源（如，/dev/LOCDEV）。同時，我假定你也有一台遠程主機，用以作為源設備的備份點（如，/dev/REMDEV）。</p>`,9)),o("p",null,[t[9]||(t[9]=n("你需要在兩台系統上具有root帳號訪問權限，並且設置從本地訪問遠程的",-1)),d(e,{href:"https://linux.cn/article-5444-1.html"},{default:s(()=>[...t[8]||(t[8]=[n("無密碼SSH訪問",-1)])]),_:1}),t[10]||(t[10]=n("。最後，你需要安裝Bdsync到兩台主機上。",-1))]),t[27]||(t[27]=r(`<p>要在本地主機上初始化一個遠程備份進程，我們需要以root執行以下命令：</p><pre><code># bdsync &quot;ssh root@remote_host bdsync --server&quot; /dev/LOCDEV /dev/REMDEV | gzip &gt; /some_local_path/DEV.bdsync.gz 
</code></pre><p>這裏需要進行一些説明。Bdsync客户端將以root打開一個到遠程主機的SSH連接，並執行帶有--server選項的Bdsync客户端。明確説明一下，/dev/LOCDEV是我們的本地主機上的源LUKS塊設備，而/dev/REMDEV是遠程主機上的目標塊設備。它們可以是/dev/sda（作為整個磁盤），或者/dev/sda2（作為單個分區）。本地Bdsync客户端的輸出結果隨後被管道輸送到gzip，用來在本地主機中創建DEV.bdsync.gz（所謂的二進制補丁文件）。</p><p>你第一次運行上面的命令的時候，它會花費很長一段時間，這取決於你的互聯網/局域網速度，以及/dev/LOCDEV的大小。記住，你必須有兩個大小相同的塊設備（/dev/LOCDEV和/dev/REMDEV）。</p><p>下一步是要將補丁文件從本地主機拷貝到遠程主機。一種方式是使用scp：</p><pre><code># scp /some_local_path/DEV.bdsync.gz root@remote_host:/remote_path 
</code></pre><p>最後一步，是要在遠程主機上執行以下命令，它們會將補丁文件應用到/dev/REMDEV：</p><pre><code># gzip -d &lt; /remote_path/DEV.bdsync.gz | bdsync --patch=/dev/DSTDEV 
</code></pre><p>我推薦在使用真實數據部署Bdsync前，使用一些（沒有任何重要數據）小分區來做這些測試。在你完全弄懂整個設置是如何工作之後，你可以開始備份真實數據。</p><h3 id="尾聲" tabindex="-1">尾聲 <a class="header-anchor" href="#尾聲" aria-label="Permalink to “尾聲”">​</a></h3><p>小結之，我們演示瞭如何使用Bdsync來為LUKS設備實施增量備份。和rsync一樣，每次備份只有一小部分數據，而不是整個LUKS設備，需要被推送到非現場備份點，這樣會節省帶寬和備份時間。剩下來，需要通過SSH或SCP來保證所有數據傳輸的安全，事實上設備自身是由LUKS加密的。也可以通過使用可以運行bdsync的專用用户（而非root）來改進該配置。我們也可以將bdsync用於任何塊設備，如LVM卷或RAID磁盤，也可以很輕易地設置Bdsync備份本地磁盤到USB驅動器上。如你所見，它有着無限可能性！</p><p>隨時分享你的想法。</p><hr>`,13)),o("p",null,[t[12]||(t[12]=n("via: ",-1)),d(e,{href:"http://xmodulo.com/remote-incremental-backup-luks-encrypted-disk-partition.html"},{default:s(()=>[...t[11]||(t[11]=[n("http://xmodulo.com/remote-incremental-backup-luks-encrypted-disk-partition.html",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=n("作者：",-1)),d(e,{href:"http://xmodulo.com/author/iulian"},{default:s(()=>[...t[13]||(t[13]=[n("Iulian Murgulet",-1)])]),_:1}),t[17]||(t[17]=n(" 譯者：",-1)),d(e,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[14]||(t[14]=[n("GOLinux",-1)])]),_:1}),t[18]||(t[18]=n(" 校對：",-1)),d(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[15]||(t[15]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[21]||(t[21]=n("本文由 ",-1)),d(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[19]||(t[19]=[n("LCTT",-1)])]),_:1}),t[22]||(t[22]=n(" 原創翻譯，",-1)),d(e,{href:"http://linux.cn/"},{default:s(()=>[...t[20]||(t[20]=[n("Linux中國",-1)])]),_:1}),t[23]||(t[23]=n(" 榮譽推出",-1))])])}const x=a(u,[["render",m]]);export{g as __pageData,x as default};
